-- ============================================================
-- 东角山 staging 测试数据 seed —— 种植 + 仓库板块
-- ============================================================
-- 用途：staging 部署后一次性铺齐种植/仓库的"前置 + 业务"数据，
--       让测试人员不被"空表 / 缺前置数据"卡住（避免把缺数据误报成 bug）。
--
-- 来源：从本地 dev 库（已联调验证、各表 FK 互相对齐的 coherent 数据）导出，
--       覆盖 35 张业务表 + 收尾的成员关系补全。
--   种植 t_plant_*    作物/地块/片区/班组/成员/种植计划/农事记录/采摘/绩效/有机认证…
--   仓库 t_warehouse_* 产品/库位/库存/需求/采购入库/生产/流水/燎毛/分割/打包/发货/盘点/追溯…
--   主数据 t_md_store / t_md_supplier
--
-- 幂等：全部 REPLACE INTO（按主键 id 覆盖），只影响导出的这些行；
--       可反复跑、不会动 staging 上这些 id 之外的数据。
--
-- 前置（staging 由 Flyway 自动具备，本脚本不重复灌）：
--   · 业务字典 sys_dict_data（整地类型/业态/单位/…）
--   · 菜单权限 sys_menu、部门 sys_dept、角色岗位
--   · 测试用户 sys_user 9100-9109（dev_plant_mgr 9103 / dev_plant_worker 9109 / dev_warehouse_mgr 9104 …）
--   · 编码规则 t_md_biz_code_rule（新建记录自动生成业务编码用）
--   若 staging 没跑过 Flyway（库是空的），先启动一次 ruoyi-admin 让它建表+灌 Flyway，再跑本脚本。
--
-- 跑法（DBeaver）：选中本库 → 直接整文件执行；或命令行
--   mysql -h<host> -u<user> -p<pwd> <db> < seed-staging-plant-warehouse.sql
--
-- 全部 tenant_id='1001'（V1 单租户）。
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;


-- ============================================================
-- 收尾：保证 mp 农事「我的记录」对测试账号可见
-- ============================================================
-- 农事「我的记录」按 work_people 成员表（user_id → team_id）过滤记录的 farm_by。
-- 约束 uk_user_active(tenant + user + del_unique)：一个用户只能在一个 active 班组，所以每账号挂一队。
-- 现有 17 条农事记录：8 条属"我的天哪"、9 条属"果蔬班"。
--   · 9103 dev_plant_mgr   → "我的天哪"（body 已带，看到 8 条）
--   · 9109 dev_plant_worker→ "果蔬班"  （此处补，看到 9 条）
-- 两队各有一个测试账号能在「我的记录」看到本队记录；用哪个账号登录就看哪队。
-- 幂等：先清 9109 的成员行再插。
DELETE FROM t_plant_work_people WHERE user_id = 9109;

-- 班组队长（admin 班组视图展示用；mp「我的记录」不依赖此列）
UPDATE t_plant_work_team SET leader_id = 9103 WHERE id = 2059550773104033793 AND del_flag = '0';
UPDATE t_plant_work_team SET leader_id = 9109 WHERE id = 2059411720249589762 AND del_flag = '0';

SET FOREIGN_KEY_CHECKS = 1;

-- 验证（跑完应符合）：
--   SELECT COUNT(*) FROM t_plant_farm_records;        -- 期望 17
--   SELECT COUNT(*) FROM t_warehouse_product_info;    -- 期望 39
--   SELECT COUNT(*) FROM t_warehouse_stock_flow;      -- 期望 58
--   SELECT user_id, team_id FROM t_plant_work_people WHERE user_id IN (9103,9109) AND del_flag='0';  -- 期望 2 行
-- 完。
